      display: flex;
      align-items: center;
      gap: 0.875rem;
      padding: 1rem 1.1rem;
      border: 1px solid var(--border);
      border-radius: 16px;
      background: var(--surface-alt);
      cursor: pointer;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

