    .submit-button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      padding: 0.9rem 1.3rem;
      min-width: 11rem;
      cursor: pointer;
      box-shadow: 0 12px 24px -16px rgba(37, 99, 235, 0.85);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
