    .submit-button:hover {
      transform: translateY(-1px);
    }

    .submit-button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .message {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .message[data-state="error"] {
      color: #b91c1c;
    }

    .message[data-state="success"] {
      color: #166534;
    }

    @media (max-width: 520px) {
      main {
        padding: 3.5rem 0.85rem;
      }

      .actions {
        align-items: stretch;
      }

      .submit-button {
        width: 100%;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-alt: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --border-strong: ButtonBorder;
        --accent: ButtonText;
        --accent-strong: ButtonText;
        --focus: Highlight;
      }

      .card,
