<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <div class="page-shell">
      <header class="hero">
        <h1>Notification preferences</h1>
        <p>Choose the delivery method that works best for you.</p>
      </header>

      <section class="card" aria-labelledby="notification-preferences-heading">
        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset>
              <legend id="notification-preferences-heading">How do you prefer to receive notifications?</legend>
              <p class="help-text" id="notification-help">Select one option before submitting.</p>

              <div class="options" aria-describedby="notification-help">
                <label class="radio-option" for="email">
                  <input type="radio" id="email" name="notification-method" value="Email" required />
                  <span>Email</span>
                </label>

                <label class="radio-option" for="sms">
                  <input type="radio" id="sms" name="notification-method" value="SMS" />
                  <span>SMS</span>
                </label>

                <label class="radio-option" for="push">
                  <input type="radio" id="push" name="notification-method" value="Push Notifications" />
                  <span>Push Notifications</span>
                </label>
              </div>
            </fieldset>

            <div class="actions">
              <button class="submit-button" type="submit">Submit</button>
              <p class="message" id="form-message" aria-live="polite"></p>
            </div>
          </div>
        </form>
      </section>
    </div>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const radios = Array.from(form.elements['notification-method']);
    const message = document.getElementById('form-message');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const selected = radios.find((radio) => radio.checked);

      if (!selected) {
        message.textContent = 'Please choose one notification method.';
        message.dataset.state = 'error';
        radios[0].focus();
        return;
      }

      message.textContent = `Saved: ${selected.value}.`;
      message.dataset.state = 'success';
    });
  </script>
</body>
</html>
